/*******************************************************************************
 * Code for BOARD_BootClockFRO96M configuration
 ******************************************************************************/
void BOARD_BootClockFRO96M_InitClockModule(clock_module_t module)
{
    bool switchBackToFIRC = false;

    switch(module) {
        case kClockModule_MainCoreSupplyMode:
            /* Get VDD_CORE_MAIN config from IFR1 for the 1.1V (Standard Drive). */
            CLOCK_GetVDDCoreMainConfig(kCLOCK_StandardDrive, &vddCoreMainConfig);
            /* Set the Vdd Core voltage of the Main domain. */
            PMU_UpdateVDDCore1P1InActiveMode(AON__PMU, vddCoreMainConfig.vddCoreMainAconfig);
            /* Set the low voltage detect trim control value for the PMU. */
            PMU_UpdateLvdLvTrim(AON__PMU, vddCoreMainConfig.lvdLvTrim);
            /* Set the high voltage detect trim control value for the PMU. */
            PMU_UpdateHvdLvTrim(AON__PMU, vddCoreMainConfig.hvdLvTrim);
            break;
        case kClockModule_AONCoreSupplyMode:
            /* Set the Vdd Core voltage of the AON domain to 0.770V to allow the AON Core operate at 10 MHz. */
            PMU_UpdateVDDCoreInActiveMode(AON__PMU, VDD_CORE_AON_0_770V_VOLTAGE_10M);
            break;
        case kClockModule_ROSC:
            /* Monitor is disabled */
            CLOCK_SetRoscMonitorMode(kSCG_RoscMonitorDisable);
            /* Initialization of the ROSC only if it is not already running. */
            if (!CLOCK_IsRoscInitialized())
            {
                /* Configuration of the 32 kHz crystal oscillator */
                CLOCK_InitRosc(&roscConfig_BOARD_BootClockFRO96M);
            }
            /* Enable the 32 kHz crystal oscillator output to the AON and the Main domains. */
            AON__SYSCON_AON->XTAL_32K_CLKCTRL &= ~SYSCON_AON_XTAL_32K_CLKCTRL_XTAL_32K_CLK_CTRL_MASK;
            /* Enable the clock output of the XTAL32K from the AON_RTC. */
            AON__CGU->CLK_CONFIG |= CGU_CLK_CONFIG_XTAL32_OUT_EN_MASK;
            /* Enable the XTAL 32.768KHz towards the CGU. */
            AON__RTC_AON->CONFIG |= RTC_CONFIG_XTAL32_EN_MASK;
            break;
        case kClockModule_FIRC:
            /* if FIRC is selected as the SCS clock source switch to the alternate SIRC clock source. */
            if (((SCG0->CSR & SCG_CSR_SCS_MASK) >> SCG_CSR_SCS_SHIFT) == CLK_ATTACH_CLK_SEL(kFIRC_to_MAIN_CLK)) {
                switchBackToFIRC = true;
                CLOCK_AttachClk(kSIRC_to_MAIN_CLK);             /* Switch MAIN_CLK to SIRC to allow FIRC reconfiguration. */
            }
            CLOCK_SetupFROHFClocking(96000000U, 0U);            /* Setup FIRC and FRO HF clock */
            SCG0->FIRCCSR &= ~SCG_FIRCCSR_LK_MASK;              /* Unlock FIRCCSR register */
            SCG0->FIRCCSR &= ~SCG_FIRCCSR_FIRCSTEN_MASK;        /* FIRC is disabled in Deep Sleep mode */
            SCG0->FIRCCSR |= SCG_FIRCCSR_LK_MASK;               /* Lock FIRCCSR register */
            if (switchBackToFIRC) {
                CLOCK_SetFlashWaitStateBasedOnFreq(96000000UL); /* Set the Flash wait states for 96000000 Hz */
                CLOCK_AttachClk(kFIRC_to_MAIN_CLK);             /* Switch MAIN_CLK back to FIRC. */
            }
            break;
        case kClockModule_SIRC:
            CLOCK_SetupFRO12MClocking();                        /* Setup FRO12M clock */
            SCG0->SIRCCSR &= ~SCG_SIRCCSR_LK_MASK;              /* Unlock SIRCCSR register */
            SCG0->SIRCCSR &= ~SCG_SIRCCSR_SIRCSTEN_MASK;        /* SIRC is disabled in Deep Sleep mode */
            SCG0->SIRCCSR |= SCG_SIRCCSR_LK_MASK;               /* Lock SIRCCSR register */
            break;
        case kClockModule_FRO:
            CLOCK_SetupFROAonClocking(10000000U);               /* Setup ROOT_CLK clock source */
            break;
        case kClockModule_FRO16K:
            PMU_EnableFRO16K(AON__PMU, true);                   /* Initialize the FRO16K clock source */
            PMU_UpdateFRO16KFreq(AON__PMU, kPMU_FRO16KOutput16KHz);/* Select the output frequency of the FRO16K */
            AON__PMU->PMU_DPD3_CTRL |= PMU_PMU_DPD3_CTRL_FRO16KHZ_ACT_MASK;/* Enable the FRO16K even during DPD3 and shutdown modes */
            break;
        case kClockModule_SystemClkDiv:
            /* !< Set AHBCLKDIV divider to value 1 */
            CLOCK_SetClockDiv(kCLOCK_DivAHBCLK, 1U);
            /* !< Set SLOWCLKDIV divider to value 4 */
            CLOCK_SetClockDiv(kCLOCK_DivAHBAIPSCLK, 4U);
            break;
        case kClockModule_AonAuxClkDiv:
            /* !< Set AONAUXCLKDIV divider to value 4 */
            CLOCK_SetClockDiv(kCLOCK_DivAONAUXCLK, 4U);
            break;
        case kClockModule_FRO_HF_DIV:
            /* !< Set FROHFDIV divider to value 1 */
            CLOCK_SetClockDiv(kCLOCK_DivFRO_HF_DIV, 1U);
            break;
        case kClockModule_SystemClkSrc:
            /* !< Set the Flash wait states for 96000000 Hz. */
            CLOCK_SetFlashWaitStateBasedOnFreq(96000000UL);
            /* !< Switch MAIN_CLK to FIRC */
            CLOCK_AttachClk(kFIRC_to_MAIN_CLK);
            break;
        case kClockModule_MRCC_FRO16K_SEL:
            /* !< Switch P16K to CLK_16K */
            CLOCK_AttachClk(kCLK_16K_to_P16K);
            break;
        case kClockModule_ROOT_AUX_CLK_SEL:
            /* !< Switch AON_ROOT_AUX to XTAL32K */
            CLOCK_AttachClk(kXTAL32K_to_AON_ROOT_AUX);
            /* !< Disable the ROOT_AUX_CLK clock for CGU */
            CLOCK_DisableClock(kCLOCK_GateAonRootAux);
            break;
        case kClockModule_AON_CPU_ROOT_CLK:
            /* !< Switch AON_CPU to FROdiv1 */
            CLOCK_AttachClk(kFROdiv1_to_AON_CPU);
            /* !< Set AON_CPU_CLK_DIV divider to value 1 */
            CLOCK_SetClockDiv(kCLOCK_DIVAonCPU, 1U);
            break;
        case kClockModule_AON_COM_CLK:
            /* !< Switch AON_COM to FROdiv4 */
            CLOCK_AttachClk(kFROdiv4_to_AON_COM);
            /* !< Set COM_GRP_CLK_DIV divider to value 1 */
            CLOCK_SetClockDiv(kCLOCK_DIVAonCMP, 1U);
            break;
        case kClockModule_CLKOUT:
            /* !< Switch CLKOUT to SLOW_CLK */
            CLOCK_AttachClk(kSLOW_CLK_to_CLKOUT);
            /* !< Set CLKOUTCLKDIV divider to value 1 */
            CLOCK_SetClockDiv(kCLOCK_DivCLKOUT, 1U);
            break;
        case kClockModule_DBG_TRACE_CLK:
            /* !< Switch DBGTRACE to CLK_16K_LS */
            CLOCK_AttachClk(kCLK_16K_LS_to_DBGTRACE);
            /* !< Set DBGTRACECLKDIV divider to value 1 */
            CLOCK_SetClockDiv(kCLOCK_DivTRACE, 1U);
            break;
        case kClockModule_CTIMER_GRP0_CLK:
            /* !< Switch CTIMERg0 to FRO_HF_DIV */
            CLOCK_AttachClk(kFRO_HF_DIV_to_CTIMERg0);
            /* !< Set CTIMERGRP0CLKDIV divider to value 1 */
            CLOCK_SetClockDiv(kCLOCK_DivCTIMER0, 1U);
            break;
        case kClockModule_CTIMER_GRP1_CLK:
            /* !< Switch CTIMERg1 to FRO_HF_DIV */
            CLOCK_AttachClk(kFRO_HF_DIV_to_CTIMERg1);
            /* !< Set CTIMERGRP1CLKDIV divider to value 2 */
            CLOCK_SetClockDiv(kCLOCK_DivCTIMER1, 2U);
            break;
        case kClockModule_ADC0_CLK:
            /* !< Switch ADC0 to FRO_HF_DIV */
            CLOCK_AttachClk(kFRO_HF_DIV_to_ADC0);
            /* !< Set ADC0CLKDIV divider to value 2 */
            CLOCK_SetClockDiv(kCLOCK_DivADC0, 2U);
            break;
        case kClockModule_SYSTICK_CLK:
            /* !< Switch SYSTICK to CPU_CLK */
            CLOCK_AttachClk(kCPU_CLK_to_SYSTICK);
            /* !< Set SYSTICKCLKDIV divider to value 1 */
            CLOCK_SetClockDiv(kCLOCK_DivSYSTICK, 1U);
            break;
        case kClockModule_PERIPH_GROUP_0_CLK:
            /* !< Switch PERIPH_GROUP0 to FRO12M */
            CLOCK_AttachClk(kFRO12M_to_PERIPH_GROUP0);
            /* !< Set PGRP0CLKDIV divider to value 1 */
            CLOCK_SetClockDiv(kCLOCK_DivPeriphGroup0, 1U);
            /* !< Enable the PERIPH_GROUP_0_CLK clock for MRCC */
            CLOCK_EnableClock(kCLOCK_GatePERIPH_GROUP0);
            break;
        case kClockModule_PERIPH_GROUP_1_CLK:
            /* !< Switch PERIPH_GROUP1 to FRO12M */
            CLOCK_AttachClk(kFRO12M_to_PERIPH_GROUP1);
            /* !< Set PGRP1CLKDIV divider to value 1 */
            CLOCK_SetClockDiv(kCLOCK_DivPeriphGroup1, 1U);
            /* !< Enable the PERIPH_GROUP_1_CLK clock for MRCC */
            CLOCK_EnableClock(kCLOCK_GatePERIPH_GROUP1);
            break;
        case kClockModule_ACMP_CLK:
            /* !< Switch CMP0 to FRO12M */
            CLOCK_AttachClk(kFRO12M_to_CMP0);
            /* !< Halt CMP0RRCLKDIV divider */
            CLOCK_SetClockDiv(kCLOCK_DivCMP0_RR, 0U);
            /* !< Set CMP0FUNCCLKDIV divider to value 1 */
            CLOCK_SetClockDiv(kCLOCK_DivCMP0_FUNC, 1U);
            break;
        case kClockModule_UTICK0_CLK:
            /* !< Switch UTICK0 to CLK_1M */
            CLOCK_AttachClk(kCLK_1M_to_UTICK0);
            break;
        case kClockModule_OSTIMER0_CLK:
            /* !< Switch OSTIMER0 to FRO16K */
            CLOCK_AttachClk(kFRO16K_to_OSTIMER0);
            break;
        case kClockModule_WWDT0_CLK:
            /* !< Set WWDT0CLKDIV divider to value 1 */
            CLOCK_SetClockDiv(kCLOCK_DivWWDT0, 1U);
            break;
        case kClockModule_AON_TMR_GRP_CLK:
            /* !< Switch AON_TMR to FROdiv4 */
            CLOCK_AttachClk(kFROdiv4_to_AON_TMR);
            break;
        case kClockModule_AON_LPTMR_CLK:
            /* !< Switch AON_LPTMR to ON_TMR */
            CLOCK_AttachClk(AON_TMR_to_AON_LPTMR);
            break;
        case kClockModule_AON_KPP_CLK:
            /* !< Switch AON_KPP to FRO16K */
            CLOCK_AttachClk(kFRO16K_to_AON_KPP);
            break;
        case kClockModule_AON_LCD_CLK:
            /* !< Switch AON_LCD to FRO16K */
            CLOCK_AttachClk(kFRO16K_to_AON_LCD);
            break;
        case kClockModule_AON_LPADC_CLK:
            /* !< Switch AON_LPADC to FROdiv4 */
            CLOCK_AttachClk(kFROdiv4_to_AON_LPADC);
            break;
        case kClockModule_AON_ACMP0_CLK:
            /* !< Switch AON_CMP0 to FROdiv4 */
            CLOCK_AttachClk(kFROdiv4_to_AON_CMP0);
            /* !< Set AON_ACMP_CLK0_DIV divider to value 1 */
            CLOCK_SetClockDiv(kCLOCK_DIVAonACMP0CLK0, 1U);
            /* !< Set AON_ACMP_CLK1_DIV divider to value 1 */
            CLOCK_SetClockDiv(kCLOCK_DIVAonACMP0CLK1, 1U);
            break;
        default:
            assert(false);
            break;
    }
}

